(()=>{'use strict';const $=id=>document.getElementById(id);
async function selectedPreview(print=false){window.renderReport?.();window.KPLanguage?.localize($('printReport'));let pages=window.KPReportPages.selected();if(!pages.length){const status=$('report-page-selection-status');status.textContent='Select at least one page to print.';status.dataset.printError='true';status.focus();return null;}const preview=window.open('','_blank');if(!preview)return null;
 const needs=pages.some(p=>['vedic-sade-sati','vedic-varshaphal'].includes(p.dataset.reportSection));if(needs){preview.document.body.textContent='Preparing selected reports…';await KPVedic.calculate();window.renderReport();window.KPLanguage?.localize($('printReport'));pages=window.KPReportPages.selected();}const styles=[...document.querySelectorAll('style')].map(n=>'<style>'+n.textContent.replace(/#kundali\b/g,'[data-report-id="kundali"]')+'</style>').join('');preview.document.open();preview.document.write('<!doctype html><html><head><meta charset="UTF-8"><title>Selected report</title>'+styles+'<style>html,body{margin:0;padding:0;background:#edf1f5}body>.report-page{display:block!important;margin:10px auto!important;box-sizing:border-box}body>.report-page:not(.kp-a4-page){width:190mm!important;height:auto!important;min-height:0!important;max-height:none!important;overflow:visible!important}.report-selection-preview-tools{position:sticky;top:0;z-index:100;padding:8px;background:#f7f9fc;display:flex;justify-content:center;gap:7px;flex-wrap:wrap}.report-selection-preview-tools button{font-size:12px;min-height:29px;padding:4px 10px}@page{size:A4;margin:10mm}@media print{.report-selection-preview-tools{display:none!important}body>.report-page{display:block!important;margin:0!important;zoom:1!important}body>.report-page:not(.kp-a4-page){width:190mm!important;min-height:0!important;height:auto!important;overflow:visible!important;break-after:page}body>.report-page:last-child{break-after:auto}}</style></head><body><div class="report-selection-preview-tools no-print"><button id="preview-save-pdf" onclick="window.print()">Print / Save PDF</button><button onclick="document.querySelectorAll(\'.report-page\').forEach(p=>p.style.zoom=Math.min(2,(parseFloat(p.style.zoom)||1)+.1))">Zoom +</button><button onclick="document.querySelectorAll(\'.report-page\').forEach(p=>p.style.zoom=Math.max(.5,(parseFloat(p.style.zoom)||1)-.1))">Zoom −</button><button onclick="window.close()">Close preview</button></div>'+pages.map(p=>p.outerHTML).join('')+'</body></html>');preview.document.close();
 for(const page of preview.document.querySelectorAll('[data-report-section="event-promise"],[data-report-section="gemstones"],[data-report-section="nadi-astrology"],[data-report-section="kp-fourfold"],[data-report-section="kp-sixfold"],[data-report-section="kp-fourstep-section"]'))window.KPA4Preview?.normalize(preview.document,page);
 window.KPLanguage?.localize(preview.document);if(print)preview.document.fonts.ready.then(()=>preview.print());return preview;}
function init(){const card=$('report').querySelector('.card.no-print'),heading=card.querySelector('h2');heading.textContent='Select reports to print';card.classList.add('report-selection-window');$('report-page-picker').querySelector('legend').textContent='Report pages';const help=$('report-page-picker').querySelector('p');help.textContent='Choose reports. Long reports continue onto additional A4 pages.';
 const actions=$('print-selected-report').parentElement;actions.className='actions report-selection-footer';const print=$('print-selected-report');print.textContent='Print';print.removeAttribute('onclick');print.addEventListener('click',()=>selectedPreview(true));
 for(const [id,text,handler] of [['report-selection-preview','Preview',()=>selectedPreview()],['report-selection-pdf','Export to PDF',()=>selectedPreview(true)],['report-selection-close','Close',()=>document.querySelector('.app-sidebar [data-tab="home"]').click()]]){const b=document.createElement('button');b.id=id;b.type='button';b.textContent=text;b.addEventListener('click',handler);actions.append(b);}
 const all=document.createElement('label');all.className='report-select-all-label';all.innerHTML='<input id="report-all-toggle" type="checkbox">Select all';$('report-page-selection-status').before(all);all.firstChild.addEventListener('change',e=>{if(e.target.checked)KPReportPages.selectAll();else KPReportPages.clear();});
 function sync(){const inputs=[...$('report-page-options').querySelectorAll('input[data-report-page-key]')],checked=inputs.filter(n=>n.checked).length,box=$('report-all-toggle');box.checked=inputs.length>0&&checked===inputs.length;box.indeterminate=checked>0&&checked<inputs.length;}
 $('report-page-options').addEventListener('change',sync);new MutationObserver(sync).observe($('report-page-selection-status'),{childList:true});sync();
 $('report-select-all').parentElement.hidden=true;
}
window.KPSelectedReport=Object.freeze({preview:selectedPreview});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,0));else init();})();
